  "tag": "CREDENTIAL_ACCESS"
}

{
  "summary": "The script uses Invoke-Command to run a PowerShell instance on a remote computer with no profile and a hidden window, executing an arbitrary command.",
  "evidence": [
    {
      "code": "Invoke-Command -ComputerName <target> -ScriptBlock {powershell -nop -w hidden -c <command>}",
      "code_explain": "Invoke-Command performs PowerShell remoting, allowing code execution on a remote host. Inside the script block a new PowerShell process is launched with '-nop' (no profile) and '-w hidden' (window hidden), which are common techniques to evade detection and run commands stealthily. The placeholder <command> could be any payload, making this pattern a strong indicator of remote command execution and defense evasion.",
      "tag": "REMOTE_COMMAND_EXECUTION"
    },
    {
      "code": "powershell -nop -w hidden -c <command>",
      "code_explain": "The '-nop' switch disables loading of the user's profile, reducing forensic artifacts. '-w hidden' creates a hidden console window, a classic defense‑evasion tactic. The '-c' flag runs an arbitrary command string, which could be used to download or execute further malicious code.",
      "tag": "DEFENSE_EVASION"
    }
  ],
  "explain": "The observable behavior—remote PowerShell remoting combined with a hidden, no‑profile PowerShell instance—matches techniques frequently used by attackers to execute payloads stealthily on target systems. While the actual payload is not shown, the pattern itself is suspicious and indicative of potential malicious activity.",
  "is_malicious": "Likely",
  "tag": "REMOTE_COMMAND_EXECUTION"
}

{
